import{_ as i,o as t,c as e,a5 as c}from"./chunks/framework.CsGesDJn.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/media-package-campaign/3-5-3-request-media-package/report3_spec.md","filePath":"feature/media-package-campaign/3-5-3-request-media-package/report3_spec.md"}'),o={name:"feature/media-package-campaign/3-5-3-request-media-package/report3_spec.md"};function a(h,n,g,l,r,s){return t(),e("div",null,[...n[0]||(n[0]=[c("<p><strong>3.5.3 Request Media package</strong></p><p><strong>Function Trigger</strong></p><p>Begins when User thực hiện thao tác trên giao diện <code>MediaPackagePage (UI)</code> liên quan đến tính năng <code>Request Media package</code>.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: User.</li><li><strong>Purpose</strong>: Với một bộ pagkage mẫu do công ty cung cấp như thế thì CLIENT sẽ được quyền thảo luận lại, đưa ra các yêu cầu về giá, về thông tin tổng quan như thời gian, ... các sự kiện, hình thức, giá và owner hoặc manager đó sẽ chấp nhận hay không hoặc chuyển đổi thành một thay đổi khác để phù hợp hơn với họ. Quá trình đó được diễn ra cho đến khi cả 2 bên chốt được gói cuối cùng..</li><li><strong>Interface</strong>: Giao diện <code>MediaPackagePage (UI)</code> hiển thị trực quan các thành phần thao tác, dữ liệu và phản hồi trạng thái.</li><li><strong>Data Processing</strong>: Tiếp nhận yêu cầu tại <code>MediaPackageController</code>, xác thực quyền của caller, thực thi kiểm tra và xử lý nghiệp vụ thông qua <code>MediaPackageService</code>, truy xuất và cập nhật cơ sở dữ liệu thông qua Repository tương ứng.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Screen Layout (<code>MediaPackagePage (UI)</code>):</p><ul><li>Header: Tiêu đề trang, breadcrumb điều hướng và thông tin định danh ngữ cảnh làm việc.</li><li>Main Workspace: Khu vực hiển thị bảng dữ liệu, biểu mẫu nhập liệu hoặc danh sách đối tượng nghiệp vụ.</li><li>Action Panel: Các nút điều khiển thực hiện hành động chính, nút hủy và các bộ lọc tìm kiếm.</li><li>Feedback Area: Khu vực hiển thị trạng thái xử lý (loading spinner, modal xác nhận, toast thông báo kết quả).</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required</strong>: Các trường bắt buộc theo đặc tả của <code>POST /api/v1/media-packages/request</code>.</li><li><strong>Input optional</strong>: Các tham số lọc, phân trang hoặc ghi chú bổ sung.</li><li><strong>System data</strong>: Bản ghi dữ liệu liên quan tại các bảng cơ sở dữ liệu (<code>MediaPackageRepository, CampaignRepository</code>).</li><li><strong>Output</strong>: <code>MediaPackageResponse</code> kèm mã trạng thái HTTP tiêu chuẩn.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-353</strong>: Chỉ các Actor có thẩm quyền hợp lệ (<code>User</code>) mới được phép kích hoạt tính năng.</li><li>Đảm bảo tính toàn vẹn dữ liệu và kiểm tra xung đột trạng thái trước khi thực hiện thay đổi dữ liệu.</li><li>Mọi thao tác đều được ghi nhận nhật ký hệ thống phục vụ công tác kiểm toán và giám sát.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Thiếu hoặc sai định dạng tham số bắt buộc → Trả về HTTP 400 <code>BAD_REQUEST</code>.</li><li>Token không hợp lệ hoặc hết hạn → Trả về HTTP 401 <code>UNAUTHORIZED</code>.</li><li>Không đủ thẩm quyền vai trò → Trả về HTTP 403 <code>FORBIDDEN</code>.</li><li>Bản ghi đối tượng không tồn tại → Trả về HTTP 404 <code>NOT_FOUND</code>.</li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>Người dùng mở giao diện <code>MediaPackagePage (UI)</code>.</li><li>Giao diện gửi yêu cầu <code>POST /api/v1/media-packages/request</code> tới <code>MediaPackageController</code>.</li><li><code>MediaPackageController</code> điều phối xử lý sang <code>MediaPackageService.processRequest()</code>.</li><li>Hệ thống thực hiện kiểm tra và xử lý dữ liệu nghiệp vụ.</li><li>Hệ thống trả dữ liệu <code>MediaPackageResponse</code> về giao diện hiển thị cho người dùng.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>2.a1: Token xác thực không hợp lệ hoặc hết hạn → Hệ thống hiển thị thông báo lỗi và yêu cầu đăng nhập lại.</li><li>3.a1: Dữ liệu đầu vào không thỏa mãn ràng buộc nghiệp vụ → Hệ thống báo lỗi chi tiết tại từng trường nhập liệu.</li><li>4.a1: Đối tượng yêu cầu không tồn tại trong hệ thống → Hiển thị thông báo không tìm thấy bản ghi tương ứng.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>Trạng thái hệ thống được cập nhật chính xác theo kết quả xử lý của tính năng <code>Request Media package</code>.</li><li>Người dùng nhận được phản hồi trực quan trên giao diện và luồng nghiệp vụ được tiếp diễn theo kế hoạch.</li></ul>",14)])])}const p=i(o,[["render",a]]);export{d as __pageData,p as default};
